mabatis.mapper.select:
select
a.algorithm_id,
a.algorithm_name,
a.algorithm_type,
a.describel,
a.algorithm_code,
a.analys_type
from t_algorithm_info a
where 1 = 1
 and a.algorithm_id = #{algorithmId, jdbcType=BIGINT}
 and a.algorithm_name = #{algorithmName, jdbcType=VARCHAR}
 and a.algorithm_type = #{algorithmType, jdbcType=VARCHAR}
 and a.describel = #{describel, jdbcType=VARCHAR}
 and a.algorithm_code = #{algorithmCode, jdbcType=INTEGER}
 and a.analys_type = #{analysType, jdbcType=VARCHAR}

select
a.algorithm_id,
a.algorithm_name,
a.algorithm_type,
a.describel,
a.algorithm_code,
a.analys_type,
b.dict_note
from t_algorithm_info a
LEFT JOIN t_dict_business b ON b.dict_code = a.analys_type
where 1 = 1
 and a.algorithm_id = #{algorithmId, jdbcType=BIGINT}
 and a.algorithm_name = #{algorithmName, jdbcType=VARCHAR}
 and a.algorithm_type = #{algorithmType, jdbcType=VARCHAR}
 and a.describel = #{describel, jdbcType=VARCHAR}
 and a.algorithm_code = #{algorithmCode, jdbcType=INTEGER}
 and a.analys_type = #{analysType, jdbcType=VARCHAR}
